<?php require 'config.php';$u=require_login();page_start('Events & workshops',$u);heading('SHOW UP. TRY SOMETHING.','Your next opportunity.','Hands-on workshops, new connections and a reason to keep building.');$events=rows('SELECT e.*, (SELECT COUNT(*) FROM registrations r WHERE r.event_id=e.id) joined,(SELECT attended+1 FROM registrations r WHERE r.event_id=e.id AND r.user_id=?) mine FROM events e ORDER BY starts_at',[$u['id']]); ?>
<div class="grid"><?php foreach($events as $ev):$past=strtotime($ev['starts_at'])<time();?><article class="card"><span class="badge"><?= $past?'Past event':'Upcoming workshop'?></span><h2><?=e($ev['title'])?></h2><p><?=e($ev['description'])?></p><p class="meta"><?=date('l, d M Y · H:i',strtotime($ev['starts_at']))?><br><?=e($ev['location'])?><br><?=$ev['joined']?> / <?=$ev['capacity']?> places filled</p><?php if($ev['mine']):?><p class="badge"><?=$ev['mine']==2?'Attendance confirmed':'You are registered'?></p><form method="post" action="action.php"><?php csrf();?><input type="hidden" name="action" value="event_leave"><input type="hidden" name="id" value="<?=$ev['id']?>"><button class="ghost">Cancel registration</button></form><?php elseif(!$past):?><form method="post" action="action.php"><?php csrf();?><input type="hidden" name="action" value="event_join"><input type="hidden" name="id" value="<?=$ev['id']?>"><button class="button" <?=$ev['joined']>=$ev['capacity']?'disabled':''?>><?=$ev['joined']>=$ev['capacity']?'Event full':'Save my place →'?></button></form><?php endif;?></article><?php endforeach;if(!$events)echo '<p>No events published yet.</p>';?></div>
<?php page_end(); ?>
